            8'd93 : ln2_nk = {32'h4280ECD4, 32'h390B5073};   // n = 93
            8'd94 : ln2_nk = {32'h42824FB8, 32'h390CCFF0};   // n = 94
            8'd95 : ln2_nk = {32'h4283B29C, 32'h390E4F6D};   // n = 95
            8'd96 : ln2_nk = {32'h42851580, 32'h390FCEEA};   // n = 96
            8'd97 : ln2_nk = {32'h42867864, 32'h39114E68};   // n = 97
            8'd98 : ln2_nk = {32'h4287DB48, 32'h3912CDE5};   // n = 98
            8'd99 : ln2_nk = {32'h42893E2C, 32'h39144D62};   // n = 99
            8'd100: ln2_nk = {32'h428AA110, 32'h3915CCDF};   // n = 100
            8'd101: ln2_nk = {32'h428C03F4, 32'h39174C5C};   // n = 101
            8'd102: ln2_nk = {32'h428D66D8, 32'h3918CBD9};   // n = 102
            8'd103: ln2_nk = {32'h428EC9BC, 32'h391A4B56};   // n = 103
            8'd104: ln2_nk = {32'h42902CA0, 32'h391BCAD3};   // n = 104
            8'd105: ln2_nk = {32'h42918F84, 32'h391D4A50};   // n = 105
            8'd106: ln2_nk = {32'h4292F268, 32'h391EC9CE};   // n = 106
            8'd107: ln2_nk = {32'h4294554C, 32'h3920494B};   // n = 107
            8'd108: ln2_nk = {32'h4295B830, 32'h3921C8C8};   // n = 108
            8'd109: ln2_nk = {32'h42971B14, 32'h39234845};   // n = 109
            8'd110: ln2_nk = {32'h42987DF8, 32'h3924C7C2};   // n = 110
            8'd111: ln2_nk = {32'h4299E0DC, 32'h3926473F};   // n = 111
            8'd112: ln2_nk = {32'h429B43C0, 32'h3927C6BC};   // n = 112
            8'd113: ln2_nk = {32'h429CA6A4, 32'h39294639};   // n = 113
            8'd114: ln2_nk = {32'h429E0988, 32'h392AC5B6};   // n = 114
            8'd115: ln2_nk = {32'h429F6C6C, 32'h392C4534};   // n = 115
            8'd116: ln2_nk = {32'h42A0CF50, 32'h392DC4B1};   // n = 116
            8'd117: ln2_nk = {32'h42A23234, 32'h392F442E};   // n = 117
            8'd118: ln2_nk = {32'h42A39518, 32'h3930C3AB};   // n = 118
            8'd119: ln2_nk = {32'h42A4F7FC, 32'h39324328};   // n = 119
            8'd120: ln2_nk = {32'h42A65AE0, 32'h3933C2A5};   // n = 120
            8'd121: ln2_nk = {32'h42A7BDC4, 32'h39354222};   // n = 121
            8'd122: ln2_nk = {32'h42A920A8, 32'h3936C19F};   // n = 122
            8'd123: ln2_nk = {32'h42AA838C, 32'h3938411C};   // n = 123
            8'd124: ln2_nk = {32'h42ABE670, 32'h3939C09A};   // n = 124
            8'd125: ln2_nk = {32'h42AD4954, 32'h393B4017};   // n = 125
            8'd126: ln2_nk = {32'h42AEAC38, 32'h393CBF94};   // n = 126
            8'd127: ln2_nk = {32'h42B00F1C, 32'h393E3F11};   // n = 127
            default: ln2_nk = 64'd0;
        endcase
    endfunction

    wire [DEPTH:0] vd;
    ot_hdc_vline #(.D(DEPTH)) u_v (.clk(clk), .rst_n(rst_n), .v(v), .vd(vd));
    assign vo = vd[DEPTH];

    // depth 1: clamp
    reg [31:0] xc;
    always @(posedge clk) begin
        if (!x[31] && x[30:0] > K_MAX[30:0]) xc <= K_MAX;
        else if (x[31] && x[30:0] > K_MINM[30:0]) xc <= {1'b1, K_MINM[30:0]};
        else xc <= x;
    end

    wire [31:0] t;
    wire [2:0] f;
    ot_hdc_qmul_f12 #(.LAT(LM)) m_t (clk, rst_n, vd[1], xc, K_LOG2E, t, f[0]);   // 1 + LM

    // n = rint-to-even(t), |t| < 127.  With E = field - 127, the integer part
    // is the significand shifted right by 23 - E (E in [-1, 6]); below E = -1,
    // |t| < 1/2 and n = 0.
    wire [23:0] tm = {1'b1, t[22:0]};
    wire [7:0]  te = t[30:23];
    wire [4:0]  tsh = 5'd23 - (te[4:0] - 5'd31);      // 23 - E, as te - 127 = te[4:0] - 31 (mod 32)
    wire [23:0] tip = tm >> tsh;
    wire [4:0]  trb = tsh - 5'd1;
    wire        thalf = tm[trb];
    wire        tstk = |(tm & ~({24{1'b1}} << trb));
    wire [7:0]  tmag = (te < 8'd126) ? 8'd0 : (tip[7:0] + {7'd0, thalf && (tstk || tip[0])});
    reg  [8:0]  nint;
    always @(posedge clk) nint <= t[31] ? -{1'b0, tmag} : {1'b0, tmag};

    reg [31:0] a_hi, a_lo;
    always @(posedge clk) {a_hi, a_lo} <= ln2_nk(nint[7:0]);

    wire [31:0] r1, r, xc_d, lo_d;
    ot_hdc_delay #(.W(32), .D(T_K - 1)) d_x (clk, rst_n, xc, xc_d);
    ot_hdc_qadd_f12 #(.LAT(LA)) a_r1 (clk, rst_n, vd[T_K], xc_d, {~a_hi[31], a_hi[30:0]}, r1, f[1]);
    ot_hdc_delay #(.W(32), .D(LA)) d_lo (clk, rst_n, a_lo, lo_d);
    ot_hdc_qadd_f12 #(.LAT(LA)) a_r  (clk, rst_n, vd[T_R1], r1, {~lo_d[31], lo_d[30:0]}, r, f[2]);

    // Horner: p = C0; six times p = p*r + C[k]; r travels in (LM+LA)-cycle hops.
    wire [31:0] rd [0:6];
    wire [31:0] pm [1:6];
    wire [31:0] pa [0:6];
    wire [12:1] hf;
    assign rd[0] = r;
    assign pa[0] = poly(0);
    genvar k;
    generate
        for (k = 1; k <= 6; k = k + 1) begin : g_h
            if (k < 6) begin : g_rd
                ot_hdc_delay #(.W(32), .D(LM + LA)) d_r (clk, rst_n, rd[k-1], rd[k]);
            end
            ot_hdc_qmul_f12 #(.LAT(LM)) u_m (clk, rst_n, vd[T_R + (LM + LA)*(k-1)], pa[k-1], rd[k-1], pm[k], hf[2*k-1]);
            ot_hdc_qadd_f12 #(.LAT(LA)) u_a (clk, rst_n, vd[T_R + (LM + LA)*(k-1) + LM], pm[k], poly(k), pa[k], hf[2*k]);
        end
    endgenerate

    wire [8:0] nint_d;
    ot_hdc_delay #(.W(9), .D(T_P - T_N)) d_n (clk, rst_n, nint, nint_d);
    always @(posedge clk) y <= pa[6] + {{14{nint_d[8]}}, nint_d, 23'd0};

    assign fault = |{f, hf};
endmodule

// 1/d: seed 0x7ef311c7 - bits(d), three Newton-Raphson steps y*(2 - d*y).
module ot_hdc_recip_q_f12 #(
    parameter integer LA = 5,
    parameter integer LM = 6
) (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        v,
    input  wire [31:0] x,
    output wire [31:0] y,
    output wire        vo,
    output wire        fault
);
    localparam integer IT = 2 * LM + LA;
    localparam integer DEPTH = 1 + 3 * IT;      // 28
    wire [DEPTH:0] vd;
    ot_hdc_vline #(.D(DEPTH)) u_v (.clk(clk), .rst_n(rst_n), .v(v), .vd(vd));
    assign vo = vd[DEPTH];

    reg [31:0] y0, d1;
    always @(posedge clk) begin
        // Keep the short pipeline bit-exact with the full pipeline when its
        // bit seed exceeds the supported finite-denominator range.
        y0 <= (!x[31] && x[30:23] != 8'hff && x > 32'h7EF311C7)
            ? 32'h00000000 : 32'h7EF311C7 - x;
        d1 <= x;
    end
    wire [31:0] yi [0:3];
    wire [31:0] dd [0:2];
    wire [31:0] m [0:2];
    wire [31:0] s [0:2];
    wire [31:0] yd [0:2];
    wire [8:0] f;
    assign yi[0] = y0;
    assign dd[0] = d1;
    genvar k;
    generate
        for (k = 0; k < 3; k = k + 1) begin : g_nr
            if (k < 2) begin : g_d
                ot_hdc_delay #(.W(32), .D(IT)) d_d (clk, rst_n, dd[k], dd[k+1]);
            end
            ot_hdc_qmul_f12 #(.LAT(LM)) m_m (clk, rst_n, vd[1 + IT*k], dd[k], yi[k], m[k], f[3*k]);
            ot_hdc_qadd_f12 #(.LAT(LA)) a_s (clk, rst_n, vd[1 + IT*k + LM], 32'h40000000, {~m[k][31], m[k][30:0]}, s[k], f[3*k+1]);
            ot_hdc_delay #(.W(32), .D(LM + LA)) d_y (clk, rst_n, yi[k], yd[k]);
            ot_hdc_qmul_f12 #(.LAT(LM)) m_y (clk, rst_n, vd[1 + IT*k + LM + LA], yd[k], s[k], yi[k+1], f[3*k+2]);
        end
    endgenerate
    assign y = yi[3];
    assign fault = |f;
endmodule

// 1/sqrt(v): seed 0x5f3759df - (bits >> 1), three steps y*(1.5 - half*(y*y)).
module ot_hdc_rsqrt_q_f12 #(
    parameter integer LA = 5,
    parameter integer LM = 6
) (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        v,
    input  wire [31:0] x,
    output wire [31:0] y,
    output wire        vo,
    output wire        fault
);
    localparam integer IT = 3 * LM + LA;
    localparam integer DEPTH = 1 + 3 * IT;      // 37
    wire [DEPTH:0] vd;
    ot_hdc_vline #(.D(DEPTH)) u_v (.clk(clk), .rst_n(rst_n), .v(v), .vd(vd));
    assign vo = vd[DEPTH];

    reg [31:0] y0;
    always @(posedge clk) y0 <= 32'h5F3759DF - {1'b0, x[31:1]};
    wire [31:0] half;
    wire [31:0] hd [0:2];
    wire [31:0] yi [0:3];
    wire [31:0] yy [0:2];
    wire [31:0] hm [0:2];
    wire [31:0] s [0:2];
    wire [31:0] yd [0:2];
    wire [12:0] f;
    ot_hdc_qmul_f12 #(.LAT(LM)) m_half (clk, rst_n, v, x, 32'h3F000000, half, f[12]);   // LM
    ot_hdc_delay #(.W(32), .D(1)) d_h0 (clk, rst_n, half, hd[0]);       // 1 + LM
    assign yi[0] = y0;
    genvar k;
    generate
        for (k = 0; k < 3; k = k + 1) begin : g_nr
            if (k < 2) begin : g_h
                ot_hdc_delay #(.W(32), .D(IT)) d_h (clk, rst_n, hd[k], hd[k+1]);
            end
            ot_hdc_qmul_f12 #(.LAT(LM)) m_yy (clk, rst_n, vd[1 + IT*k],             yi[k], yi[k], yy[k], f[4*k]);
            ot_hdc_qmul_f12 #(.LAT(LM)) m_hm (clk, rst_n, vd[1 + IT*k + LM],        hd[k], yy[k], hm[k], f[4*k+1]);
            ot_hdc_qadd_f12 #(.LAT(LA)) a_s  (clk, rst_n, vd[1 + IT*k + 2*LM],      32'h3FC00000, {~hm[k][31], hm[k][30:0]}, s[k], f[4*k+2]);
            ot_hdc_delay #(.W(32), .D(2*LM + LA)) d_y (clk, rst_n, yi[k], yd[k]);
            ot_hdc_qmul_f12 #(.LAT(LM)) m_y  (clk, rst_n, vd[1 + IT*k + 2*LM + LA], yd[k], s[k], yi[k+1], f[4*k+3]);
        end
    endgenerate
    assign y = yi[3];
    assign fault = |f;
endmodule

`timescale 1ns/1ps
// ---------------------------------------------------------------------------
// Segmented reducer of the vector stream unit (ot_hdc_vstream): SW lanes a
// cycle, one segment per outer iteration, a segment's vectors back to back.
//
// THE ARITHMETIC CONTRACT (R-ARITH, shared with the DeepSeek-V4.1 core; the
// golden is tools/hdc_golden.py reduce_chunked): a segment of n elements is
// cut into contiguous chunks of 8, each summed sequentially from +0,
// ((((((x0 + x1) + x2) + x3) + x4) + x5) + x6) + x7, and the chunk sums are
// added by a pairwise tree ((c0 + c1) + (c2 + c3)) + ... padded with +0.  The
// order does not depend on SW: lane l of vector v holds element v*SW + l, so
// a vector is SW/8 whole chunks, its chunk sums form an aligned subtree, and
// the vectors' subtrees combine pairwise in time (below).  Elements past n
// arrive as +0 and padding chunks and vectors are +0: adding +0 is exact, so
// the result is the golden's.  MAX is the same structure with max for +
// (order-free).  `sq` squares every element first.
//
// Pipeline (every stage one result a cycle; the adder and multiplier are the
// low-latency units of rtl/hdc/ot_hdc_fastfp.sv, LA = LM = 3):
//   SQ    optional square                                      LM (+1)
//   CHAIN per chunk, 7 chained ops, lane 8k+j delayed LA(j-1)   7 LA
//   TREE  log2(SW/8) pairwise levels inside the vector          LA + 1 a level
//   TIME  LV levels pairing the segment's vectors in time: a level holds a
//         left operand until its right sibling arrives; a segment's LAST
//         item combines with a held left operand or passes (its sibling is
//         +0); every path has the op's latency, so items stay in order
//                                                               LA + 1 a level
// A segment of at most 2^LV vectors ends with its LAST item at the top;
// an item leaving the top without LAST (a longer segment) raises `fault`.
// ---------------------------------------------------------------------------
module ot_hdc_vred_op_f12 #(
    parameter integer LA = 3
) (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        v,
    input  wire        mx,         // 1: max, 0: add
    input  wire [31:0] a,
    input  wire [31:0] b,
    output wire [31:0] y,
    output wire        fault
);
    function automatic [31:0] okey(input [31:0] x);
        okey = x[31] ? ~x : {1'b1, x[30:0]};
    endfunction
    wire [31:0] ys, ym;
    wire f, mxd;
    ot_hdc_qadd_f12 #(.LAT(LA)) u_add (clk, rst_n, v && !mx, a, b, ys, f);
    ot_hdc_delay #(.W(33), .D(LA)) u_m (.clk(clk), .rst_n(rst_n),
        .d({mx, (okey(a) >= okey(b)) ? a : b}), .q({mxd, ym}));
    assign y = mxd ? ym : ys;
    assign fault = f;
endmodule

module ot_hdc_vreduce_f12 #(
    parameter integer LA = 5,
    parameter integer LM = 6,
    parameter integer SW = 8,          // lanes, a multiple of 8
    parameter integer LV = 4,          // time levels: segments of up to 2^LV vectors
    parameter integer AW = 24
) (
    input  wire            clk,
    input  wire            rst_n,
    input  wire            v_in,       // a vector of the reduction
    input  wire            mx_in,      // MAX (else SUM)
    input  wire            sq_in,      // reduce x*x
    input  wire            last_in,    // the segment's last vector
    input  wire [AW-1:0]   addr_in,    // result address (with the last vector)
    input  wire [SW*32-1:0] x_in,      // elements; past the segment: +0 (SUM) or a real element (MAX)
    output reg             o_we,
    output reg  [AW-1:0]   o_addr,
    output reg  [31:0]     o_data,
    output wire            busy,
    output reg             fault
);
    localparam integer CD = 7 * LA;          // the 8-element chain
    localparam integer NC = SW / 8;
    localparam integer LC = $clog2(NC);
    localparam integer TAG = 1 + 1 + AW;   // mx, last, addr

    // -- SQ: every element takes the squaring stage (fixed depth) ------------------
    wire [SW*32-1:0] xsq, xd;
    wire [SW-1:0]    fsq;
    genvar l;
    generate for (l = 0; l < SW; l = l + 1) begin : g_sq
        ot_hdc_qmul_f12 #(.LAT(LM)) u_sq (clk, rst_n, v_in && sq_in, x_in[32*l +: 32], x_in[32*l +: 32], xsq[32*l +: 32], fsq[l]);
    end endgenerate
    wire [SW*32-1:0] xq;
    wire [TAG-1:0]   tq;
    wire             vq, sqq;
    ot_hdc_delay #(.W(SW*32 + TAG + 1), .D(LM)) u_sqd (.clk(clk), .rst_n(rst_n),
        .d({x_in, mx_in, last_in, addr_in, sq_in}), .q({xd, tq, sqq}));
    wire [LM:0] vqs;
    ot_hdc_vline #(.D(LM)) u_vq (.clk(clk), .rst_n(rst_n), .v(v_in), .vd(vqs));
    reg  [SW*32-1:0] c_x;
    reg  [TAG-1:0]   c_t;
    reg              c_v;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) c_v <= 1'b0;
        else c_v <= vqs[LM];
    end
    always @(posedge clk) begin
        c_x <= sqq ? xsq : xd;
